// All facts remain linked to their own source and edition.
const safeURL=url=>{try{const u=new URL(url,location.href);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
function sourceLink(d,item){const source=d.sources.find(s=>s.id===item.source);return source?`<a class="fact-source" href="${esc(safeURL(source.url))}" target="_blank" rel="noopener">${esc(item.koReference||item.reference||source.koLabel||source.label)} ↗</a>`:''}
function unavailable(text){return `<div class="empty-block"><h3>원문에서 확인되지 않은 항목</h3><p>${esc(text)}</p></div>`}
function koreanFact(item){
  const used=new Set(),glosses=item.glosses||[];
  const text=(item.ko||item.value).split(/([,，]\s*|\n)/).map(part=>{const term=part.trim().replace(/\.$/,''),g=glosses.find(x=>x.term===term);if(!g)return part;used.add(term);return `${g.meaning} (${term})`}).join('');
  const notes=glosses.filter(g=>!used.has(g.term));
  return `<p>${esc(text).replaceAll('\n','<br>')}</p>`+(notes.length?'<dl class="term-notes">'+notes.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.meaning)}</dd></div>`).join('')+'</dl>':'')+(item.ko&&item.ko!==item.value?`<details class="original-text"><summary>문헌 원문 보기</summary><p lang="ko">${esc(item.value).replaceAll('\n','<br>')}</p></details>`:'');
}
function sourceFact(d,item){return `<div class="source-fact">${koreanFact(item)}${sourceLink(d,item)}</div>`}
function factList(d,items,limit=2){if(!items?.length)return '';let first=items.slice(0,limit).map(x=>sourceFact(d,x)).join('');if(items.length>limit)first+=`<details class="more-facts"><summary>다른 문헌 ${items.length-limit}건 보기</summary>${items.slice(limit).map(x=>sourceFact(d,x)).join('')}</details>`;return first}
function sectionBody(id,html){const section=$('#'+id),heading=section.querySelector('.section-heading');section.replaceChildren(heading);section.insertAdjacentHTML('beforeend',html)}
const baseOpenHerb=openHerb;
openHerb=function(id){baseOpenHerb(id);const r=records.find(x=>x.id===id);if(!r?.detail)return;const d=r.detail;
  $('.hero h1').innerHTML=esc(r.name)+' <span>'+esc(r.hanja)+'</span>';
  $('.hero-copy p').textContent=[r.english,r.latin].filter(Boolean).join(' · ')||r.plant;
  $('.eyebrow').textContent=r.latin?.toUpperCase()||'HERBAL MATERIA MEDICA';
  $('.pill').textContent=d.koClassification||d.classification||'생약 정보';
  $('.overview').innerHTML=[['약용 부위',d.part||'기원 정의 참조'],['기원',r.plant],['분류',d.koClassification||d.classification||r.category],['자료 상태',d.origins.length?'출처별 정보 수록':'식약처 목록 정보']].map(([k,v])=>`<div><p>${esc(k)}<strong>${esc(v)}</strong></p></div>`).join('');
  const table=[['한약명',esc(r.name+' '+r.hanja)],['생약명 / 영문명',esc([r.latin,r.english].filter(Boolean).join(' / ')||'해당 원문에 미기재')],['학명 (변종은 기원 참조)',esc(d.taxa?.join(' / ')||'기원 정의 참조')],['과명',esc(d.family||'기원 정의 참조')],['기원 정의',d.origins.length?factList(d,d.origins,1):esc(r.plant)],['성질·맛 / 관련 경락',d.natures.length?factList(d,d.natures,1):'대조한 원문에 미기재'],['다른 이름',d.aliases.length?factList(d,d.aliases,1):'대조한 원문에 미기재'],['산지',d.region?esc(d.region):'출처에서 확인한 약재 생산지 정보 없음']];
  sectionBody('basic','<table><tbody>'+table.map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')+'</tbody></table><p class="source-note">성질·맛은 전통적 분류이며 실제 온도를 뜻하지 않습니다. 관련 경락(귀경)의 간·심·비·폐·신 등은 한의학의 기능 체계로, 현대의학의 특정 장기 효과를 뜻하지 않습니다. 한글로 읽기 쉽게 정리했으며 문헌 원문도 펼쳐 볼 수 있습니다.</p>');
  const tags=[...new Set(d.effects.flatMap(x=>(x.ko||x.value).split(/[,，]/)).map(s=>s.trim().replace(/\.$/,'')).filter(s=>s&&s.length<55))].slice(0,3);
  sectionBody('effects',(tags.length?'<div class="effect-cards">'+tags.map(t=>`<div><span>전통 효능</span><h3>${esc(d.effects.flatMap(x=>x.glosses||[]).find(g=>g.term===t.replace(/\.$/,''))?.meaning||t)}</h3><small>${esc(t)}</small></div>`).join('')+'</div>':'')+(d.effects.length?factList(d,d.effects):unavailable('이름이 일치하는 원문에서 효능 분류를 확인하지 못했습니다.'))+(d.indications.length?'<h3 class="subheading">문헌에서 사용한 증상 (주치)</h3>'+factList(d,d.indications):'')+'<p class="section-note">전통의학의 용어와 문헌상 사용 기록입니다. 현대 임상에서 치료 효과가 확립되었다는 의미는 아닙니다.</p>');
  sectionBody('usage',(d.doses.length?'<p class="section-note">아래는 문헌에 기재된 용량·용법입니다. 원문에서 1일량·1회량을 명시하지 않은 값에는 그 기준을 덧붙이지 않았습니다. 개인 복용량으로 사용하지 마세요.</p><div class="dose-table"><table><thead><tr><th>문헌</th><th>기재 용량·용법</th></tr></thead><tbody>'+d.doses.map(x=>`<tr><th>${sourceLink(d,x)}</th><td>${koreanFact(x)}</td></tr>`).join('')+'</tbody></table></div>':unavailable('대조한 자료에 용량·용법이 없거나, 항목을 안전하게 구분할 수 없어 원문 확인이 필요합니다.'))+(d.preparations.length?'<h3 class="subheading">약재 손질·가공·보관 (포제)</h3>'+factList(d,d.preparations.map(x=>({...x,value:x.label+' · '+x.value,ko:(x.koLabel||x.label)+' · '+(x.ko||x.value)}))):''));
  sectionBody('safety','<div class="warning"><h3>문헌에 기록된 주의사항·금기</h3>'+(d.cautions.length?factList(d,d.cautions,3):'<p>대조한 원문에 개별 금기가 없거나 명확히 추출되지 않았습니다. 안전하다는 의미는 아닙니다.</p>')+'</div><p class="section-note">임신·수유 여부와 복용 중인 약물을 의료진에게 알리세요. 이 문헌 정보는 최신 상호작용 목록이나 의료진의 판단을 대신하지 않습니다.</p>');
  const seen=new Set();const formulas=d.formulas.filter(f=>{const key=f.url+'|'+f.name;if(seen.has(key))return false;seen.add(key);return true});
  const formulaCard=f=>`<a class="formula-link" href="${esc(safeURL(f.url))}" target="_blank" rel="noopener"><span><strong>${esc(f.koName||f.name)}</strong><small>${esc(f.koReference||f.reference||'약학정보원 처방정보')}</small></span><span>↗</span></a>`;
  sectionBody('formulas',formulas.length?'<p class="section-note">처방 예시 또는 구성 약재명으로 확인한 연결입니다. 같은 이름의 처방도 출전·포제·배합량이 다를 수 있습니다.</p><div class="formula-list">'+formulas.slice(0,8).map(formulaCard).join('')+'</div>'+(formulas.length>8?`<details class="more-facts"><summary>관련 처방 ${formulas.length-8}건 더 보기 (전체 ${formulas.length}건)</summary>${formulas.slice(8).map(formulaCard).join('')}</details>`:''):unavailable('약학정보원 본초 처방 예시, 처방정보 100건과 방약합편 564건에서 확인된 연결이 없습니다. 관련 처방이 전혀 없다는 의미는 아닙니다.'));
  sectionBody('images','<div class="gallery-tabs" role="group" aria-label="이미지 종류"><button class="active" data-gallery="plant">원식물</button><button data-gallery="herb">약재</button><button data-gallery="slice">절편</button><button data-gallery="region">산지별 비교</button></div><div id="gallery-content"></div>');
  sectionBody('sources','<ol class="sources">'+d.sources.map(s=>`<li><a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener">${esc(s.koLabel||s.label)} ↗</a></li>`).join('')+'</ol><div class="review-meta"><span>자료 확인일 <b>'+esc(d.updated)+'</b></span><span>검토자 <b>'+esc(d.reviewer)+'</b></span></div><p class="source-note">기관 원문을 보존하면서 한글 표기와 주요 용어의 학습용 풀이를 덧붙였습니다. 약재·처방의 고유 이름은 뜻을 바꾸지 않고 한글로 읽도록 표기했습니다. 수록 공정서의 개정 연도는 각 출처 표기를 확인하세요. 자동 대조 후 일부 대표 약재를 점검했으며 전체 자료의 전문가 검토는 완료되지 않았습니다.</p>');
  bindArticle();render();
};
gallery=function(type){const r=records.find(x=>x.id===current);const d=r?.detail;document.querySelectorAll('[data-gallery]').forEach(b=>{b.classList.toggle('active',b.dataset.gallery===type);b.setAttribute('aria-pressed',String(b.dataset.gallery===type))});if(!d)return;
  const images=d.images.filter(i=>i.type===type);
  $('#gallery-content').innerHTML=images.length?'<div class="reference-gallery">'+images.map(i=>`<figure><a href="${esc(i.path)}" target="_blank" rel="noopener" aria-label="${esc(i.caption)} 크게 보기"><img class="gallery-photo reference-photo" src="${esc(i.path)}" alt="${esc(i.caption)}" loading="lazy"></a><figcaption><strong>${esc(i.caption)}</strong><p>${esc(i.note||'')}</p><a href="${esc(safeURL(i.source))}" target="_blank" rel="noopener">${esc(i.credit)} ↗</a><span> · ${esc(i.license)}</span></figcaption></figure>`).join('')+'</div>':unavailable(type==='slice'&&current==='sophorae-flos'?'괴화는 꽃·꽃봉오리 약재입니다. 감별도감의 괴각 단면은 열매 자료여서 여기에 사용하지 않았습니다.':type==='region'?'채집지나 촬영지는 약재 생산지와 다릅니다. 같은 기준으로 비교할 산지별 약재 사진을 확인하지 못했습니다.':'현재 대조한 자료에서 이 약재에 정확히 대응하는 공개 이용 이미지를 연결하지 못했습니다.');
};
